class Solution {
    int m, n;
    int dfs(int r, int c, std::vector<std::vector<int>>& grid) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == 0) return 0;
        int gold = grid[r][c];
        grid[r][c] = 0;
        int best = std::max({
            dfs(r + 1, c, grid),
            dfs(r - 1, c, grid),
            dfs(r, c + 1, grid),
            dfs(r, c - 1, grid)
        });
        grid[r][c] = gold;
        return gold + best;
    }
public:
    int getMaximumGold(std::vector<std::vector<int>>& grid) {
        m = grid.size();
        n = grid[0].size();
        int ans = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] > 0) ans = std::max(ans, dfs(i, j, grid));
            }
        }
        return ans;
    }
};

class Solution {
    int m, n;
    int dfs(int r, int c, int[][] grid) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == 0) return 0;
        int gold = grid[r][c];
        grid[r][c] = 0;
        int best = Math.max(
            Math.max(dfs(r + 1, c, grid), dfs(r - 1, c, grid)),
            Math.max(dfs(r, c + 1, grid), dfs(r, c - 1, grid))
        );
        grid[r][c] = gold;
        return gold + best;
    }
    public int getMaximumGold(int[][] grid) {
        m = grid.length;
        n = grid[0].length;
        int ans = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) ans = Math.max(ans, dfs(i, j, grid));
            }
        }
        return ans;
    }
}

var getMaximumGold = function(grid) {
    const m = grid.length, n = grid[0].length;
    const dfs = (r, c) => {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] === 0) return 0;
        const gold = grid[r][c];
        grid[r][c] = 0;
        const best = Math.max(
            dfs(r + 1, c),
            dfs(r - 1, c),
            dfs(r, c + 1),
            dfs(r, c - 1)
        );
        grid[r][c] = gold;
        return gold + best;
    };

    let ans = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] > 0) ans = Math.max(ans, dfs(i, j));
        }
    }
    return ans;
};
